style.css:
@-moz-document domain("tests.kod-u.ru") {
/* ===== ФОН — ОДНА КАРТИНКА ===== */
  html, body {
    background-color: #0d0d14 !important;
    background-image: url("https://i.imgur.com/ТВОЯКАРТИНКА.png");
    background-size: 500px;
    background-position: right bottom;
    background-repeat: no-repeat;
    background-attachment: fixed;
    position: relative;
  }

  /* Тёмная вуаль, чтобы текст читался поверх тяночки */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(10, 8, 20, 0.78);
    backdrop-filter: blur(2px);
    z-index: -1;
    pointer-events: none;
  }

  /* ===== ОСНОВНОЙ КОНТЕНТ ===== */
  #region-main,
  .course-content,
  .coursebox,
  .box,
  .generalbox,
  .singleview,
  #page-content {
    background: rgba(18, 16, 28, 0.9) !important;
    color: #e8e6f0 !important;
    border-radius: 12px;
    box-shadow: 0 4px 20px rgba(255, 105, 180, 0.18);
    padding: 15px;
  }

  /* ===== ШАПКА / НАВИГАЦИЯ ===== */
  .navbar,
  .navbar-inner,
  .navbar-fixed-top,
  #page-header,
  #page-navbar {
    background: rgba(12, 10, 22, 0.95) !important;
    border-bottom: 1px solid rgba(255, 105, 180, 0.45) !important;
    box-shadow: none !important;
  }

  /* ===== ССЫЛКИ ===== */
  a, a:visited {
    color: #ff9ecb !important;
    transition: color 0.2s ease;
  }
  a:hover {
    color: #ffd1e8 !important;
    text-shadow: 0 0 8px rgba(255, 105, 180, 0.9);
  }

  /* ===== ТЕКСТ ===== */
  p, span, div, li, td, th, h1, h2, h3, h4, h5, h6, label, .coursename, .coursebox .info {
    color: #e8e6f0 !important;
  }

  /* ===== ЗАГОЛОВКИ ===== */
  h1, h2, h3, h4, h5, h6, .caption, .headingblock {
    color: #ffb3d9 !important;
    text-shadow: 0 0 10px rgba(255, 105, 180, 0.45);
  }

  /* ===== ВВОД / ФОРМЫ ===== */
  input, textarea, select, .form-control {
    background: rgba(30, 26, 45, 0.92) !important;
    color: #fff !important;
    border: 1px solid rgba(255, 105, 180, 0.45) !important;
    border-radius: 6px;
  }
  input:focus, textarea:focus, select:focus {
    outline: none;
    border-color: #ff69b4 !important;
    box-shadow: 0 0 10px rgba(255, 105, 180, 0.6);
  }

  /* ===== КНОПКИ ===== */
  .btn, .btn-primary, button, input[type="submit"], .btn-default {
    background: linear-gradient(135deg, #ff69b4, #b06ab3) !important;
    color: #fff !important;
    border: none !important;
    border-radius: 8px !important;
    font-weight: 600;
    transition: all 0.2s ease;
  }
  .btn:hover, .btn-primary:hover, button:hover, input[type="submit"]:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 15px rgba(255, 105, 180, 0.65);
  }

  /* ===== КОД / ПРИМЕРЫ ===== */
  pre, code {
    background: rgba(10, 8, 20, 0.96) !important;
    color: #a8e6cf !important;
    border-radius: 6px;
    border-left: 3px solid #ff69b4;
  }

  /* ===== ТАБЛИЦЫ (оценки, списки) ===== */
  table, tbody, thead, tr, td, th {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
    border-color: rgba(255, 105, 180, 0.2) !important;
  }

  /* Чередование строк */
  table tr:nth-child(odd)  { background-color: rgba(255, 255, 255, 0.03) !important; }
  table tr:nth-child(even) { background-color: rgba(255, 105, 180, 0.08) !important; }

  /* Ховер на строку */
  table tr:hover td,
  table tr:hover th {
    background-color: rgba(255, 105, 180, 0.25) !important;
  }

  /* ===== БЛОКИ КУРСОВ ===== */
  .coursebox {
    background: rgba(18, 16, 28, 0.92) !important;
    border: 1px solid rgba(255, 105, 180, 0.25) !important;
    border-radius: 10px;
    margin-bottom: 12px;
  }
  .coursebox .coursename a {
    color: #ffb3d9 !important;
  }

  /* ===== СКРОЛЛБАР ===== */
  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-track { background: #0d0d14; }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(#ff69b4, #b06ab3);
    border-radius: 10px;
  }

  /* ============================================================
     ЗАМЕНА НАЗВАНИЯ САЙТА (логотип-текст "test.kod-u")
     ============================================================ */

  /* 1. Прячем оригинальный текст логотипа */
  .navbar .brand,
  a.brand,
  .brand {
    font-size: 0 !important;
    color: transparent !important;
    text-decoration: none !important;
  }

  /* 2. Убираем возможный фон */
  .navbar .brand,
  a.brand {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
  }

  /* 3. Рисуем свой текст через ::after */
  .navbar .brand::after,
  a.brand::after {
    content: "ТВОЙ ТЕКСТ ТУТ"; /* ← меняй тут */
    display: inline-block;
    font-family: "Segoe UI", Arial, sans-serif;
    font-size: 22px;
    font-weight: 800;
    letter-spacing: 1px;
    color: #ff9ecb;
    text-shadow:
      0 0 12px rgba(255, 105, 180, 0.7),
      0 0 24px rgba(255, 105, 180, 0.4);
    padding: 8px 0 8px 8px;
    vertical-align: middle;
    transition: all 0.25s ease;
  }

  /* 4. Эффект при наведении */
  .navbar .brand:hover::after,
  a.brand:hover::after {
    color: #ffd1e8;
    text-shadow:
      0 0 16px rgba(255, 105, 180, 1),
      0 0 32px rgba(255, 105, 180, 0.6);
  }
}
